def maximum(arr, k):
    def quickselect(nums, k):
        if len(nums) == 1:
            return nums[0]

        pivot = nums[len(nums) // 2]
        left = [x for x in nums if x < pivot]
        mid = [x for x in nums if x == pivot]
        right = [x for x in nums if x > pivot]

        L, M = len(left), len(mid)

        if k < L:
            return quickselect(left, k)
        elif k < L + M:
            return pivot
        else:
            return quickselect(right, k - L - M)

    if k == 0:
        return []

    # Find the kth largest element (k-th maximum)
    # Since quickselect finds kth smallest, find kth largest by k' = len(arr) - k
    kth_largest = quickselect(arr, len(arr) - k)

    # Collect all elements greater than kth_largest
    greater = [x for x in arr if x > kth_largest]

    # Count how many times kth_largest should be included
    count_kth = k - len(greater)

    # Take count_kth times kth_largest
    result = greater + [kth_largest] * count_kth

    # Now sort result ascending without built-in sort
    # Using insertion sort for simplicity and O(k^2) is fine since k <= len(arr) <= 1000
    for i in range(1, len(result)):
        key = result[i]
        j = i - 1
