    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        return "No solution"
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return "No solution"

    max_x = n // a if a > 0 else 0
    # If a < 0, smallest x is 0 up to some upper bound, but since x must be non-negative,
    # and a*x must not exceed n, we try from 0 up to n // a if a > 0,
    # else up to some large number (but infinite loops are dangerous).
    # To keep it general:
    # We'll consider x in [0, n] if a > 0 else 0 up to n (because a*x must be <= n)
    # but if a < 0, a*x is negative or zero, so a*x + b*y = n with y non-negative may be impossible.
    # So just try x from 0 to n (safe upper bound).
    if a < 0:
        max_x = n if n >= 0 else 0
    max_x = max(max_x, 0)

    for x in range(max_x + 1):
        remain = n - a * x
        if remain < 0:
            continue
        if b != 0 and remain % b == 0:
            y = remain // b
            if y >= 0:
                return (x, y)
    return "No solution"

