def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x]: number of sequences of length i ending with element x
    # Elements are from 1 to m
    if n == 1:
        return m

    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1  # sequences of length 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # For each possible current element x, sum dp[y] where y <= x//2
        # To do this efficiently, build prefix sums of dp
        prefix_sum = [0] * (m + 1)
        for i in range(1, m + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp[i]

        for x in range(1, m + 1):
            max_prev = x // 2
            if max_prev >= 1:
                new_dp[x] = prefix_sum[max_prev]
            else:
                new_dp[x] = 0
        dp = new_dp

    return sum(dp[1:])

