            return student.get('height'), student.get('width')
        elif isinstance(student, (list, tuple)) and len(student) >= 2:
            return student[0], student[1]
        else:
            return None, None

    filtered = []
    for s in students:
        h, w = get_hw(s)
        if h is None or w is None:
            continue
        if min_height is not None and h < min_height:
            continue
        if max_height is not None and h > max_height:
