def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # If all digits are '9', the next palindrome is 10...01 (length+1 digits)
    if all(ch == '9' for ch in s):
        return num + 2  # e.g. 9->11, 99->101, 999->1001 etc.

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def mirror_left_to_right(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    # Increment the middle part (the left half + middle if odd)
    def increment_left(left: str) -> str:
        left_num = int(left) + 1
        return str(left_num)

    # Construct palindrome candidate from left half
    odd = (length % 2 != 0)
    left_half = s[: (length + 1)//2]

    # Generate palindrome by mirroring left half
    palindrome = mirror_left_to_right(left_half, odd)
    if int(palindrome) > num:
        return int(palindrome)

    # If palindrome <= num, increment the left half and mirror again
    incremented_left = increment_left(left_half)
    # If incrementing changes length (e.g. 999 -> 1000), we need to handle separately
    if len(incremented_left) > len(left_half):
        # This means number length increases by 1, palindrome will be like 100...001
        return int('1' + ('0' * (length - 1)) + '1')

    palindrome = mirror_left_to_right(incremented_left, odd)
    return int(palindrome)

