def find_solution(a, b, n):
    # We want to find non-negative integers x, y such that a*x + b*y = n.
    # If no such (x,y) exist, return None.
    # a, b, n are integers.

    # Handle trivial cases:
    if n < 0:
        return None
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Extended Euclidean Algorithm to find gcd and one solution
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return gcd, x, y

    gcd, x0, y0 = extended_gcd(a, b)

    if n % gcd != 0:
        return None  # no integer solutions at all

    # scale the particular solution
    x0 *= n // gcd
    y0 *= n // gcd

    # a*x + b*y = n has infinite solutions:
    # x = x0 + k*(b/gcd)
    # y = y0 - k*(a/gcd)

    # We want non-negative x,y:
    # x0 + k*(b/gcd) >= 0  => k >= -x0 * gcd / b
    # y0 - k*(a/gcd) >= 0  => k <= y0 * gcd / a

    # b/gcd and a/gcd are positive (or zero? but a,b nonzero here)
    # So find k range:
    from math import ceil, floor

    k_min = ceil(-x0 * gcd / b)
    k_max = floor(y0 * gcd / a)

    if k_min > k_max:
        return None

    # We want any k in [k_min, k_max], choose the one that minimizes x or y,
    # but any will do. Let's pick k = k_min to get smallest non-negative x.

    k = k_min
    x = x0 + k * (b // gcd)
    y = y0 - k * (a // gcd)

    if x < 0 or y < 0:
        return None

    return (x, y)

