    if not isinstance(d, dict):
        return 0

    max_depth = 1  # current level counts as 1
    for v in d.values():
        if isinstance(v, dict):
            depth = 1 + dict_depth(v)
            if depth > max_depth:
                max_depth = depth
        elif isinstance(v, (list, tuple)):
            for item in v:
                if isinstance(item, dict):
                    depth = 1 + dict_depth(item)
                    if depth > max_depth:
                        max_depth = depth
                elif isinstance(item, (list, tuple)):
                    # Traverse nested lists/tuples at same depth level
                    stack = [item]
                    while stack:
                        current = stack.pop()
                        for elem in current:
                            if isinstance(elem, dict):
                                depth = 1 + dict_depth(elem)
                                if depth > max_depth:
