def get_total_number_of_sequences(m: int, n: int) -> int:
    # dp[pos][val] = number of sequences of length pos starting with val
    # pos ranges from 1 to n
    # val ranges from 1 to m

    if n == 0:
        return 0
    if n == 1:
        # Any element from 1 to m can form a sequence of length 1
        return m

    dp = [ [0]*(m+1) for _ in range(n+1) ]

    # Base case: sequences of length 1
    for val in range(1, m+1):
        dp[1][val] = 1

    for pos in range(2, n+1):
        # For each dp[pos][val], sum over dp[pos-1][prev] where val >= 2*prev
        # i.e. prev <= val//2
        # So for each val, sum dp[pos-1][1..val//2]

        # To optimize summing, precompute prefix sums of dp[pos-1]
        prefix = [0]*(m+1)
        for i in range(1, m+1):
            prefix[i] = prefix[i-1] + dp[pos-1][i]

        for val in range(1, m+1):
            max_prev = val // 2
            if max_prev >= 1:
                dp[pos][val] = prefix[max_prev]
            else:
                dp[pos][val] = 0

    return sum(dp[n][1:])

