def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, x1, y1 = extended_gcd(y, x % y)
        return gcd, y1, x1 - (x // y) * y1

    gcd, x, y = extended_gcd(a, b)
    if n % gcd != 0:
        return None  # no solution

    x *= n // gcd
    y *= n // gcd
    return x, y

def next_power_of_2(n: int) -> int:
    if n <= 0:
        return 1
    power = 1
    while power < n:
        power <<= 1
    return power

