def substract_elements(t1, t2):
    def flatten(t):
        for el in t:
            if isinstance(el, tuple):
                yield from flatten(el)
            else:
                yield el
    elems1 = list(flatten(t1))
    elems2 = list(flatten(t2))
    length = max(len(elems1), len(elems2))
    # Extend shorter list with zeros
    elems1.extend([0]*(length - len(elems1)))
    elems2.extend([0]*(length - len(elems2)))
    return tuple(a - b for a, b in zip(elems1, elems2))

def lucky_num(n):
    numbers = list(range(1, 2 * n * 10, 2))  # start with odd numbers, oversize to ensure enough lucky numbers
    idx = 1
    while len(numbers) < n or idx < len(numbers):
        if idx >= len(numbers):
            break
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number
        del numbers[step - 1::step]
        idx += 1
    return numbers[:n]

def get_noOfways(N: int) -> int:
    if N == 0:
        return 1
    if N == 1:
        return 1
    # dp[i] will store number of ways to tile 2xi board
    dp = [0] * (N + 1)
    dp[0], dp[1] = 1, 1
    for i in range(2, N + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[N]
